    const sequence = ++fileReadSequence.current;
    setReadingFile(true);
    setFileName(file.name);
    const reader = new FileReader();
    reader.onload = async (e) => {
        let parserReady = false;
        try {
            const XLSX = await import('xlsx');
            if (sequence !== fileReadSequence.current)
                return;
            parserReady = true;
            const data = new Uint8Array(e.target?.result as ArrayBuffer);
            const workbook = XLSX.read(data, { type: 'array' });
            const sheetName = workbook.SheetNames[0];
            const sheet = workbook.Sheets[sheetName];
            const jsonData = XLSX.utils.sheet_to_json<Record<string, any>>(sheet, { defval: '', raw: false });
            if (jsonData.length === 0) {
                toast.error('文件中没有数据');
                return;
            }
            const existingPhones = new Set(existingCustomers.map(c => phoneMatchKey(c.phone, c.country)).filter(Boolean));
            const existingNames = new Set(existingCustomers.map(c => c.business_name?.trim()).filter(Boolean));
            const filePhones = new Set<string>();
            const fileNames = new Set<string>();
            const rows: ParsedRow[] = jsonData.map((row, idx) => {
                const errors: string[] = [];
                const mapped: Record<string, any> = {};
                for (const [header, value] of Object.entries(row)) {
                    const fieldKey = HEADER_MAP[header.trim()];
                    if (fieldKey) {
                        mapped[fieldKey] = fieldKey === 'phone' ? String(value) : String(value).trim();
                    }
                }
                if (!mapped.business_name)
                    errors.push('缺少商家名称');
                if (!mapped.contact_name)
                    errors.push('缺少联系人');
                if (!mapped.phone)
                    errors.push('缺少电话');
                const phoneResult = parsePhoneNumber(mapped.phone, mapped.country);
                if (mapped.phone && !phoneResult.isValid)
                    errors.push(phoneResult.reason);
                mapped.country = normalizePhoneCountry(mapped.country) || mapped.country || null;
                if (mapped.industry) {
                    mapped.industry = INDUSTRY_REVERSE[mapped.industry] || mapped.industry;
                    if (!['restaurant', 'nail', 'massage', 'beauty', 'supermarket', 'other'].includes(mapped.industry)) {
                        mapped.industry = 'other';
                    }
                }
                else {
                    mapped.industry = 'restaurant';
                }
                if (mapped.source) {
                    mapped.source = SOURCE_REVERSE[mapped.source] || mapped.source;
                    if (!['phone', 'referral', 'ads', 'private', 'returning', 'other'].includes(mapped.source)) {
                        mapped.source = 'phone';
