                    if (!['new', 'following', 'closed', 'paused', 'lost'].includes(mapped.status)) {
                        mapped.status = 'new';
                    }
                }
                else {
                    mapped.status = 'new';
                }
                mapped.has_ordering_system = ['是', 'true', '1', 'yes'].includes(String(mapped.has_ordering_system || '').toLowerCase());
                mapped.monthly_orders = parseInt(String(mapped.monthly_orders || '0'), 10) || 0;
                if (!mapped.state)
                    mapped.state = 'CA';
                if (!mapped.current_platform)
                    mapped.current_platform = '无';
                let isDuplicate = false;
                let duplicateField = '';
                const phone = phoneResult.e164;
                const name = mapped.business_name?.trim();
                if (phone && existingPhones.has(phone)) {
                    isDuplicate = true;
                    duplicateField = `电话 "${phone}" 已存在`;
                }
                else if (name && existingNames.has(name)) {
                    isDuplicate = true;
                    duplicateField = `商家名称 "${name}" 已存在`;
                }
                if (!isDuplicate && phone) {
                    if (filePhones.has(phone)) {
                        isDuplicate = true;
                        duplicateField = `文件内电话 "${phone}" 重复`;
                    }
                }
                if (!isDuplicate && name) {
                    if (fileNames.has(name)) {
